export function assertRelationalSchema() {
  if (relationships.length < 2) throw new Error("Relational schema is required.");
  return relationships.map((relation) => relation.from + " -> " + relation.to);
}

import { applyBookingsMutation, removeBookingsRecord, transitionBookingsRecord } from "@/lib/availability-engine";

export const statusFlow = [
  "Requested",
  "Confirmed",
  "Completed"
] as const;

export function handleBookingsAction(records: Array<{ id: string; label: string; value: string; status: string; meta?: string; parentId?: string }>, body: { action?: string; id?: string; label?: string; value?: string; status?: string }) {
  if (body.action === "transition" && body.id) return transitionBookingsRecord(records, body.id, [...statusFlow]);
  if (body.action === "delete" && body.id) return removeBookingsRecord(records, body.id);
  return applyBookingsMutation(records, { label: body.label || "Booking request", value: body.value || "New", status: body.status || statusFlow[0] || "Created" });
}

type RecordItem = { id: string; label: string; value: string; status: string; meta?: string; parentId?: string };

export function applyBookingsMutation(records: RecordItem[], input: Pick<RecordItem, "label" | "value" | "status">) {
  const created = { id: crypto.randomUUID?.() || String(Date.now()), ...input, meta: "book slot", parentId: records[0]?.id };
  return {
    records: [created, ...records],
    event: "book slot: " + created.label,
  };
}

export function transitionBookingsRecord(records: RecordItem[], id: string, flow: string[]) {
  let changed = "No record changed";
  const nextRecords = records.map((record) => {
    if (record.id !== id) return record;
    const index = flow.indexOf(record.status);
    const status = flow[Math.min(index + 1, flow.length - 1)] || "Done";
    changed = record.label + " moved to " + status;
    return { ...record, status };
  });
  return { records: nextRecords, event: changed };
}

export function removeBookingsRecord(records: RecordItem[], id: string) {
  const target = records.find((record) => record.id === id);
  return {
    records: records.filter((record) => record.id !== id && record.parentId !== id),
    event: target ? "Removed " + target.label : "Removed record",
  };
}

